import * as z4core from "zod/v4/core";
/**
 * Authored schemas can come from a different zod copy than this package's,
 * so the version check is structural (`_zod` marks zod 4), never
 * `instanceof`.
 */
export function isZodV4Schema(schema) {
    return "_zod" in schema;
}
/**
 * `io: "input"` for data a caller sends in (fields with a default stay
 * optional); `io: "output"` for data this side sends out. Unrepresentable
 * types become `{}` rather than failing discovery, as the zod 3 converter did.
 */
export function zodV4ToJsonSchema(schema, io) {
    const params = { io, unrepresentable: "any" };
    // Classic schemas carry their own converter; mini schemas do not.
    const converted = "toJSONSchema" in schema && typeof schema.toJSONSchema === "function"
        ? schema.toJSONSchema(params)
        : z4core.toJSONSchema(schema, params);
    return converted;
}
